export const collectionPolicy={version:'1.0',timezone:'Asia/Shanghai',weights:{relevance:.25,impact:.25,credibility:.20,novelty:.10,watchlist:.10,corroboration:.10},minimum:{relevance:70,impact:60},status:'configured_not_connected'};
// A deterministic decision helper. Production extraction/review integrations are not enabled.
export function assessCandidate(input){const values=Object.keys(collectionPolicy.weights);if(!input||!input.scores||values.some(k=>!Number.isFinite(input.scores[k])||input.scores[k]<0||input.scores[k]>100))throw Error('六项评分须为 0–100 的数字');if(!Array.isArray(input.sources)||input.sources.some(s=>!s||!['A','B','C','D'].includes(s.grade)||typeof s.chainId!=='string'||!s.chainId.trim()))throw Error('来源须含有效等级与证据链 ID');const chains=new Set(input.sources.filter(s=>s.grade==='B').map(s=>s.chainId));const evidence=input.fieldsValidated===true&&(input.sources.some(s=>s.grade==='A')||chains.size>=2);const score=values.reduce((sum,k)=>sum+input.scores[k]*collectionPolicy.weights[k],0);if(input.risk||!evidence)return {score:Math.round(score*10)/10,decision:'REVIEW',reason:input.risk?'存在风险或字段冲突':'证据门槛不足或字段未校验'};if(input.scores.relevance>=70&&input.scores.impact>=60)return {score:Math.round(score*10)/10,decision:'BRIEF',reason:'证据、相关性与影响门槛通过'};return {score:Math.round(score*10)/10,decision:'WATCH',reason:'保存候选，进入更多关注'};}
